import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

export type NetworkTokenActivationDataRequest = {
  /**
   * A block of data automatically generated by Adyen's SDK for network token provisioning. This
   * `sdkOutput` is required to create provisioning data for the network token.
   *
   * For more information, see the repositories for Adyen's SDKs for network token provisioning:
   * * [Adyen Apple Pay Provisioning
   *   SDK](https://github.com/Adyen/adyen-apple-pay-provisioning-ios).
   * * [Adyen Google Wallet Provisioning SDK](https://github.com/Adyen/adyen-issuing-android)
   */
  sdkOutput?: string;
};

export const networkTokenActivationDataRequestSchema: Schema<NetworkTokenActivationDataRequest> =
  s.object<NetworkTokenActivationDataRequest>({
    sdkOutput: s.optional(s.string()),
  });
